<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\UserGroupMembership\Domain\ValueObject\Holder;

use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Features\Access\UserGroupMembership\Domain\ValueObject\UserGroupMembershipRelyingPartyVO;
use Civi\Lughauth\Features\Access\RelyingParty\Domain\RelyingPartyRef;

trait UserGroupMembershipRelyingPartyAttributeHolder
{
    protected UserGroupMembershipRelyingPartyVO|RelyingPartyRef|null $relyingParty = null;
    protected bool $relyingPartyAssigned = false;

    public function getRelyingPartyOrDefault(?UserGroupMembershipRelyingPartyVO $relyingParty): ?UserGroupMembershipRelyingPartyVO
    {
        return $this->relyingPartyAssigned ? ($this->relyingParty !== null ? UserGroupMembershipRelyingPartyVO::from($this->relyingParty) : null) : $relyingParty;
    }
    public function relyingParty(UserGroupMembershipRelyingPartyVO|RelyingPartyRef|null $relyingParty): static
    {
        $this->relyingParty = $relyingParty;
        $this->relyingPartyAssigned = true;
        return $this;
    }
    public function getRelyingParty(): ?RelyingPartyRef
    {
        return $this->relyingParty instanceof UserGroupMembershipRelyingPartyVO ? $this->relyingParty->value() : $this->relyingParty;
    }
    public function isRelyingPartyAssigned(): bool
    {
        return $this->relyingPartyAssigned;
    }
    public function writeRelyingPartyTo(mixed $att): void
    {
        if ($this->relyingPartyAssigned) {
            $att->relyingParty($this->relyingParty);
        }
    }
    public function readRelyingPartyFrom(mixed $att): void
    {
        if ($att->isRelyingPartyAssigned()) {
            $relyingParty = $att->getRelyingParty();
            $this->relyingParty($relyingParty);
        }
    }
    public function unsetRelyingParty(): static
    {
        $this->relyingPartyAssigned = false;
        return $this;
    }
    protected function withDefaultRelyingParty(): void
    {
    }
    protected function withAssertedRelyingPartyRules(self $value, ConstraintFailList $errorsList): void
    {
        if ($value->relyingPartyAssigned = $this->relyingPartyAssigned) {
            $value->relyingParty = UserGroupMembershipRelyingPartyVO::tryFrom($this->relyingParty, $errorsList);
        }
    }
}
